def build_independent(rng):
    rows=[]
    for category, phrases in EXPRESSIONS.items():
        phrases=phrases.split("|")
        assert len(phrases)==20,(category,len(phrases))
        for i, text in enumerate(phrases):
            e=example(text,ROLES[category],category,rng,family="independent_"+category+"_"+str(i))
            rows.append(e)
    assert len(rows)==400
    return rows
